@sig trait RecoverySupervisor_Api {
  def id: Art.BridgeId
  def recovery_transition_Id : Art.PortId
  def prior_recovery_state_Id : Art.PortId

  // Logika spec var representing port state for outgoing data port
  @spec var prior_recovery_state: Docking_Access_Supervisor.RecoveryState.Type = $

  def put_prior_recovery_state(value : Docking_Access_Supervisor.RecoveryState.Type) : Unit = {
    Contract(
      Modifies(prior_recovery_state),
      Ensures(
        prior_recovery_state == value
      )
    )
    Spec {
      prior_recovery_state = value
    }

    Art.putValue(prior_recovery_state_Id, Docking_Access_Supervisor.RecoveryState_Payload(value))
  }

  def logInfo(msg: String): Unit = {
    Art.logInfo(id, msg)
  }

  def logDebug(msg: String): Unit = {
    Art.logDebug(id, msg)
  }

  def logError(msg: String): Unit = {
    Art.logError(id, msg)
  }
}

@datatype class RecoverySupervisor_Initialization_Api (
  val id: Art.BridgeId,
  val recovery_transition_Id : Art.PortId,
  val prior_recovery_state_Id : Art.PortId) extends RecoverySupervisor_Api

@datatype class RecoverySupervisor_Operational_Api (
  val id: Art.BridgeId,
  val recovery_transition_Id : Art.PortId,
  val prior_recovery_state_Id : Art.PortId) extends RecoverySupervisor_Api {

  // Logika spec var representing port state for incoming data port
  @spec var recovery_transition: Docking_Access_Supervisor.RecoveryTransition = $

  def get_recovery_transition() : Option[Docking_Access_Supervisor.RecoveryTransition] = {
    Contract(
      Ensures(
        Res == Some(recovery_transition)
      )
    )
    val value : Option[Docking_Access_Supervisor.RecoveryTransition] = Art.getValue(recovery_transition_Id) match {
      case Some(Docking_Access_Supervisor.RecoveryTransition_Payload(v)) => Some(v)
      case Some(v) =>
        Art.logError(id, s"Unexpected payload on port recovery_transition.  Expecting 'Docking_Access_Supervisor.RecoveryTransition_Payload' but received ${v}")
        None[Docking_Access_Supervisor.RecoveryTransition]()
      case _ => None[Docking_Access_Supervisor.RecoveryTransition]()
    }
    return value
  }
}
